sys_script_email.script:
(function runMailScript(/* GlideRecord */ current, /* TemplatePrinter */ template,
          /* Optional EmailOutbound */ email, /* Optional GlideRecord */ email_action,
          /* Optional GlideRecord */ event) {


         //template.print('sssssss');
		 //template.print('<br/>');
         //template.print('aaaaaa');
         //template.print('<br/>');

		 //var p1 = event.parm1;
		 email.addAddress('cc',event.parm1 + '');
          var rs = new GlideRecord('sys_user');
          rs.addQuery('user_name','tom_it_admin');
          rs.query();
          let tmpEmail ='';
		  while (rs.next()) {
             tmpEmail = rs.getValue('email');
          }
		  email.addAddress('cc',tmpEmail + '');


		 //template.print(p1);  


})(current, template, email, email_action, event);
